namespace ghidra.file.formats.android.dex.analyzer;

using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.file.analyzers;
using ghidra.file.formats.android.cdex;
using ghidra.file.formats.android.dex.format;
using ghidra.framework.options;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util.exception;
using ghidra.util.task;

public class DexHeaderFormatAnalyzer : FileFormatAnalyzer {

	private static readonly string CREATE_FRAGMENTS_OPTION_NAME = "Create Fragments";
	private static readonly bool CREATE_FRAGMENTS_DEFAULT = true;

	private bool isCreateFragments = CREATE_FRAGMENTS_DEFAULT;

	/* @Override */
	public bool analyze(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		Address baseAddress = toAddr(program, 0x0);

		if (getDataAt(program, baseAddress) != null) {
			log.appendMsg("data already exists.");
			return true;
		}

		DexHeaderFormatMarkup markup = new DexHeaderFormatMarkup(this, program, baseAddress);
		markup.markup(monitor, log);

		return true;
	}

	bool isCreateFragments() {
		return isCreateFragments;
	}

	/* @Override */
	public void removeEmptyFragments(Program program)
    {
		base.removeEmptyFragments(program);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		ByteProvider provider = MemoryByteProvider.createProgramHeaderByteProvider(program, false);
		return DexConstants.isDexFile(provider) || CDexConstants.isCDEX(program);
	}

	/* @Override */
	public AnalyzerType getAnalysisType() {
		return AnalyzerType.BYTE_ANALYZER;
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return true;
	}

	/* @Override */
	public string getDescription() {
		return "Android Dalvik EXecutable (DEX) / Compact DEX (CDEX) Header Format";
	}

	/* @Override */
	public string getName() {
		return "Android DEX/CDEX Header Format";
	}

	/* @Override */
	public AnalysisPriority getPriority() {
		return new AnalysisPriority(0);
	}

	/* @Override */
	public bool isPrototype() {
		return false;
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
		base.registerOptions(options, program);//do super
		options.registerOption(CREATE_FRAGMENTS_OPTION_NAME, CREATE_FRAGMENTS_DEFAULT, null,
			"If selected, then create Program Tree fragments for each DEX element. Disable to speed up analysis.");
	}

	/* @Override */
	public void optionsChanged(Options options, Program program) {
		base.optionsChanged(options, program);//do super

		isCreateFragments = options.getBoolean(CREATE_FRAGMENTS_OPTION_NAME,
			CREATE_FRAGMENTS_DEFAULT);
	}

}
